import sharp from 'sharp';

// Normaliza a foto enviada: gira pelo EXIF, JPG, lado maior até 3000 px.
export async function normalizar(buf: Buffer) {
  const out = await sharp(buf).rotate().resize({ width: 3000, height: 3000, fit: 'inside', withoutEnlargement: true }).jpeg({ quality: 92 }).toBuffer({ resolveWithObject: true });
  return { buf: out.data, width: out.info.width, height: out.info.height };
}

// Marca d'água diagonal da prévia, em resolução reduzida.
export async function marcaDagua(buf: Buffer) {
  const small = await sharp(buf).resize({ width: 1400, height: 1400, fit: 'inside' }).toBuffer();
  const { width = 1400, height = 1400 } = await sharp(small).metadata();
  const img = sharp(small);
  const fs = Math.round(Math.min(width, height) / 14);
  const svg = Buffer.from(`<svg width="${width}" height="${height}" xmlns="http://www.w3.org/2000/svg">
    <g transform="rotate(-28 ${width / 2} ${height / 2})" fill="white" fill-opacity="0.55" font-family="Arial, sans-serif" font-size="${fs}" letter-spacing="${fs / 5}" text-anchor="middle">
      <text x="${width / 2}" y="${height / 2 - fs * 2}">LUCIDA ROOM · prévia</text>
      <text x="${width / 2}" y="${height / 2 + fs}">LUCIDA ROOM · prévia</text>
      <text x="${width / 2}" y="${height / 2 + fs * 4}">LUCIDA ROOM · prévia</text>
    </g></svg>`);
  return img.composite([{ input: svg }]).jpeg({ quality: 80 }).toBuffer();
}

// Recorte centralizado por código, sem IA.
export async function recorte(buf: Buffer, ratio: string) {
  const [a, b] = ratio.split(':').map(Number);
  const m = await sharp(buf).metadata();
  const W = m.width!, H = m.height!;
  let w = W, h = Math.round(W * b / a);
  if (h > H) { h = H; w = Math.round(H * a / b); }
  return sharp(buf).extract({ left: Math.round((W - w) / 2), top: Math.round((H - h) / 2), width: w, height: h }).jpeg({ quality: 95 }).toBuffer();
}

