import { createServerClient } from '@supabase/ssr';
import { createClient } from '@supabase/supabase-js';
import { cookies } from 'next/headers';

export function sbUser() {
  const store = cookies();
  return createServerClient(process.env.NEXT_PUBLIC_SUPABASE_URL!, process.env.NEXT_PUBLIC_SUPABASE_ANON_KEY!, {
    cookies: {
      getAll: () => store.getAll(),
      setAll: (list) => { try { list.forEach(({ name, value, options }) => store.set(name, value, options)); } catch {} }
    }
  });
}

// acesso total, só no servidor
export function sbAdmin() {
  return createClient(process.env.NEXT_PUBLIC_SUPABASE_URL!, process.env.SUPABASE_SERVICE_ROLE_KEY!, { auth: { persistSession: false } });
}

export async function currentUser() {
  const { data } = await sbUser().auth.getUser();
  return data.user;
}

export const isAdmin = (email?: string | null) =>
  !!email && email.toLowerCase() === (process.env.ADMIN_EMAIL || '').toLowerCase();

export async function signedUrl(path: string, seconds = 3600) {
  const { data } = await sbAdmin().storage.from('fotos').createSignedUrl(path, seconds);
  return data?.signedUrl || '';
}
